def resolve(path, cwd, links):
    # Validate inputs
    if not isinstance(cwd, str) or not cwd.startswith('/'):
        return None

    # Normalize cwd - should be canonical
    if cwd != '/' and cwd.endswith('/'):
        return None

    # Start with cwd if path is relative
    if not path.startswith('/'):
        if cwd == '/':
            current = path
        else:
            current = cwd + '/' + path
    else:
        current = path

    # Split into components
    components = current.split('/')

    # Process components
    resolved = []
    link_count = 0
    i = 0

    while i < len(components):
        comp = components[i]
        i += 1

        # Skip empty components and '.'
        if comp == '' or comp == '.':
            continue

        # Handle '..'
        if comp == '..':
            if resolved:
                resolved.pop()
            # else: stay at root
            continue

        # Regular component - append it
        resolved.append(comp)

        # Check if current path is a symlink
        if resolved:
            current_path = '/' + '/'.join(resolved)
        else:
            current_path = '/'

        if current_path in links:
            # Follow the symlink
            link_count += 1
            if link_count > 8:
                return None

            target = links[current_path]

            # Remove the last component we just added
            resolved.pop()

            # If target is absolute, start from root
            if target.startswith('/'):
                resolved = []
                target_components = target.split('/')[1:]  # Skip empty first element
            else:
                # Target is relative to the directory containing the link
                # Resolved now points to the parent directory of the link
                target_components = target.split('/')

            # Insert target components back into processing
            components = target_components + components[i:]
            i = 0

    # Build result
    if resolved:
        return '/' + '/'.join(resolved)
    else:
        return '/'

